import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  User, Contact, Case, CalendarEvent, ChatMessage, UserRole, 
  EventStatus
} from '../types';
import { MOCK_USERS, MOCK_CONTACTS, MOCK_CASES, MOCK_EVENTS } from '../mockData';

interface AppContextType {
  currentUser: User;
  users: User[];
  contacts: Contact[];
  cases: Case[];
  events: CalendarEvent[];

  // Actions
  switchUser: (userId: string) => void;
  addEvent: (event: CalendarEvent) => void;
  updateEvent: (event: CalendarEvent) => void;
  updateEventDate: (eventId: string, newDate: string) => void;
  deleteEvent: (eventId: string) => void;
  addCase: (caseItem: Case) => void;
  addContact: (contact: Contact) => void;
  addChatMessage: (eventId: string, text: string) => void;

  // Permission Helpers
  canCreate: () => boolean;
  canEdit: (itemOwnerId?: string) => boolean; // itemOwnerId for Intern specific checks
  canDelete: () => boolean;
  canViewAll: () => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [users] = useState<User[]>(MOCK_USERS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [cases, setCases] = useState<Case[]>(MOCK_CASES);
  const [events, setEvents] = useState<CalendarEvent[]>(MOCK_EVENTS);

  // Permission Logic
  const canCreate = () => {
    // Admin can create anything. Lawyer can create (assumed for daily tasks). Intern only for themselves.
    // Prompt said: "Advogado pode visualizar tudo mas não pode alterar dados diferente do admin"
    // Strict interpretation: Lawyer is Read-Only except maybe Chat?
    // Let's implement Strict:
    return currentUser.role === UserRole.ADMIN;
  };

  const canEdit = (itemOwnerId?: string) => {
    if (currentUser.role === UserRole.ADMIN) return true;
    if (currentUser.role === UserRole.LAWYER) return false; // Lawyer is read-only
    if (currentUser.role === UserRole.INTERN) {
      // Intern can possibly edit their own tasks? Prompt says "apenas o que é para o seu usuario"
      return false; // Safest for "can't alter data" unless strict logic added. Let's make Intern read-only for now too to be safe with prompt.
    }
    return false;
  };

  const canDelete = () => currentUser.role === UserRole.ADMIN;

  const canViewAll = () => currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.LAWYER;

  // Actions
  const switchUser = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const addEvent = (event: CalendarEvent) => {
    setEvents([...events, event]);
  };

  const updateEvent = (updatedEvent: CalendarEvent) => {
    setEvents(events.map(e => e.id === updatedEvent.id ? updatedEvent : e));
  };

  const updateEventDate = (eventId: string, newDate: string) => {
    // Allow move if Admin, or if Intern moving their own task? 
    // Prompt says "Agenda... onde possa arrastar". Assuming Admin does this mainly.
    if (currentUser.role !== UserRole.ADMIN) {
        // If strict requirement "Lawyer can't alter", they can't drag.
        // We will check permission in the UI.
        return; 
    }
    setEvents(prev => prev.map(e => e.id === eventId ? { ...e, date: newDate } : e));
  };

  const deleteEvent = (eventId: string) => {
    setEvents(prev => prev.filter(e => e.id !== eventId));
  };

  const addCase = (caseItem: Case) => {
    setCases([...cases, caseItem]);
  };

  const addContact = (contact: Contact) => {
    setContacts([...contacts, contact]);
  };

  const addChatMessage = (eventId: string, text: string) => {
    // Chat is the exception: All users involved can chat.
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      userId: currentUser.id,
      text,
      timestamp: new Date().toISOString(),
    };

    setEvents(prev => prev.map(e => {
      if (e.id === eventId) {
        return { ...e, chatMessages: [...e.chatMessages, newMessage] };
      }
      return e;
    }));
  };

  return (
    <AppContext.Provider value={{
      currentUser,
      users,
      contacts,
      cases,
      events,
      switchUser,
      addEvent,
      updateEvent,
      updateEventDate,
      deleteEvent,
      addCase,
      addContact,
      addChatMessage,
      canCreate,
      canEdit,
      canDelete,
      canViewAll,
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { CalendarEvent, EventType, EventStatus, UserRole } from '../types';
import { Card, Badge, Modal, Button, Input } from './ui/LayoutComponents';
import { ChevronLeft, ChevronRight, Clock, MessageSquare, Briefcase, Plus, CheckCircle, GripVertical } from 'lucide-react';
import EventDetailsModal from './EventDetailsModal';

const DAYS = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];

export default function Agenda() {
  const { events, currentUser, updateEventDate, canCreate, users } = useApp();
  const [currentWeekStart, setCurrentWeekStart] = useState(new Date());
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | null>(null);

  // Helper to get dates for the week
  const getWeekDates = (startDate: Date) => {
    const dates = [];
    const start = new Date(startDate);
    // Adjust to get Sunday as start or Monday. Let's assume Sunday start for simpler logic or adjust to Monday.
    // Let's make Monday first.
    const day = start.getDay();
    const diff = start.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
    const monday = new Date(start.setDate(diff));

    for (let i = 0; i < 7; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      dates.push(d);
    }
    return dates;
  };

  const weekDates = getWeekDates(currentWeekStart);

  const handlePrevWeek = () => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() - 7);
    setCurrentWeekStart(newDate);
  };

  const handleNextWeek = () => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() + 7);
    setCurrentWeekStart(newDate);
  };

  // Drag and Drop Logic
  const handleDragStart = (e: React.DragEvent, eventId: string) => {
    if (currentUser.role !== UserRole.ADMIN) return; // Only admin moves
    e.dataTransfer.setData('eventId', eventId);
  };

  const handleDrop = (e: React.DragEvent, dateStr: string) => {
    e.preventDefault();
    if (currentUser.role !== UserRole.ADMIN) return;
    const eventId = e.dataTransfer.getData('eventId');
    if (eventId) {
      updateEventDate(eventId, dateStr);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Necessary to allow dropping
  };

  // Filter events for the user
  const visibleEvents = events.filter(e => {
    if (currentUser.role === UserRole.ADMIN) return true;
    if (currentUser.role === UserRole.LAWYER) return true;
    if (currentUser.role === UserRole.INTERN) {
      return e.assignedToIds.includes(currentUser.id);
    }
    return false;
  });

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-slate-800">Agenda Semanal</h2>
        <div className="flex items-center space-x-2">
          <Button variant="outline" onClick={handlePrevWeek}><ChevronLeft size={16}/></Button>
          <span className="text-sm font-medium w-32 text-center">
            {weekDates[0].toLocaleDateString('pt-BR')} - {weekDates[6].toLocaleDateString('pt-BR')}
          </span>
          <Button variant="outline" onClick={handleNextWeek}><ChevronRight size={16}/></Button>
          {canCreate() && (
             <Button className="ml-4" onClick={() => {/* Logic to open create modal handled in parent/or here */}}>
                <Plus size={16} className="mr-1"/> Novo
             </Button>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-x-auto overflow-y-hidden bg-slate-100 rounded-lg border border-slate-200">
        <div className="flex h-full min-w-[1000px]">
          {weekDates.map((date) => {
            const dateStr = date.toISOString().split('T')[0];
            const isToday = new Date().toISOString().split('T')[0] === dateStr;
            const dayEvents = visibleEvents.filter(e => e.date === dateStr);

            return (
              <div 
                key={dateStr}
                className={`flex-1 flex flex-col border-r border-slate-200 last:border-r-0 min-w-[140px] ${isToday ? 'bg-blue-50/50' : ''}`}
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, dateStr)}
              >
                <div className={`p-2 text-center border-b border-slate-200 ${isToday ? 'bg-blue-100' : 'bg-slate-50'}`}>
                  <p className="text-xs font-semibold text-slate-500 uppercase">{DAYS[date.getDay()]}</p>
                  <p className={`text-lg font-bold ${isToday ? 'text-blue-700' : 'text-slate-800'}`}>
                    {date.getDate()}
                  </p>
                </div>

                <div className="flex-1 p-2 overflow-y-auto space-y-2">
                  {dayEvents.map(event => (
                    <div
                      key={event.id}
                      draggable={currentUser.role === UserRole.ADMIN}
                      onDragStart={(e) => handleDragStart(e, event.id)}
                      onClick={() => setSelectedEvent(event)}
                      className={`
                        bg-white p-2 rounded shadow-sm border border-slate-200 cursor-pointer hover:shadow-md transition-shadow
                        ${currentUser.role === UserRole.ADMIN ? 'cursor-move' : ''}
                        ${event.status === EventStatus.COMPLETED ? 'opacity-60 bg-slate-50' : ''}
                      `}
                    >
                      <div className="flex justify-between items-start mb-1">
                        <Badge variant={event.type === EventType.APPOINTMENT ? 'info' : 'warning'}>
                          {event.type === EventType.APPOINTMENT ? 'Compromisso' : 'Tarefa'}
                        </Badge>
                        {event.status === EventStatus.COMPLETED && <CheckCircle size={14} className="text-green-500"/>}
                      </div>

                      <p className="text-sm font-semibold text-slate-800 leading-tight mb-1">{event.title}</p>

                      {event.time && (
                        <div className="flex items-center text-xs text-slate-500 mb-1">
                          <Clock size={12} className="mr-1" /> {event.time}
                        </div>
                      )}

                      <div className="flex items-center justify-between mt-2">
                         <div className="flex -space-x-1 overflow-hidden">
                            {event.assignedToIds.map(uid => {
                                const user = users.find(u => u.id === uid);
                                if (!user) return null;
                                return (
                                    <img 
                                        key={uid}
                                        className="inline-block h-4 w-4 rounded-full ring-1 ring-white"
                                        src={user.avatar}
                                        alt={user.name}
                                        title={user.name}
                                    />
                                );
                            })}
                         </div>
                         {event.chatMessages.length > 0 && (
                            <div className="flex items-center text-xs text-slate-400">
                                <MessageSquare size={12} className="mr-1"/> {event.chatMessages.length}
                            </div>
                         )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {selectedEvent && (
        <EventDetailsModal 
            event={selectedEvent} 
            isOpen={!!selectedEvent} 
            onClose={() => setSelectedEvent(null)} 
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { CalendarEvent, EventType, EventStatus, UserRole } from '../types';
import { Modal, Button, Badge } from './ui/LayoutComponents';
import { Send, Clock, Calendar, CheckCircle, User as UserIcon } from 'lucide-react';

interface Props {
  event: CalendarEvent;
  isOpen: boolean;
  onClose: () => void;
}

export default function EventDetailsModal({ event, isOpen, onClose }: Props) {
  const { users, cases, currentUser, addChatMessage, updateEvent, canEdit } = useApp();
  const [message, setMessage] = useState('');

  const assignedUsers = users.filter(u => event.assignedToIds.includes(u.id));
  const relatedCase = cases.find(c => c.id === event.caseId);

  const handleSendMessage = () => {
    if (!message.trim()) return;
    addChatMessage(event.id, message);
    setMessage('');
  };

  const toggleStatus = () => {
    if (!canEdit()) return;
    const newStatus = event.status === EventStatus.COMPLETED ? EventStatus.PENDING : EventStatus.COMPLETED;
    updateEvent({ ...event, status: newStatus });
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Detalhes do Evento">
      <div className="space-y-6">

        {/* Header Info */}
        <div className="flex justify-between items-start">
           <div>
              <h3 className="text-xl font-bold text-slate-900">{event.title}</h3>
              <div className="flex items-center space-x-2 mt-1 text-sm text-slate-500">
                <span className="flex items-center"><Calendar size={14} className="mr-1"/> {new Date(event.date).toLocaleDateString()}</span>
                {event.time && <span className="flex items-center"><Clock size={14} className="mr-1"/> {event.time}</span>}
              </div>
           </div>
           <Badge variant={event.status === EventStatus.COMPLETED ? 'success' : event.type === EventType.APPOINTMENT ? 'info' : 'warning'}>
              {event.status === EventStatus.COMPLETED ? 'Concluído' : event.type === EventType.APPOINTMENT ? 'Compromisso' : 'Tarefa'}
           </Badge>
        </div>

        {/* Action Button for Status */}
        {canEdit() && (
             <Button variant={event.status === EventStatus.COMPLETED ? 'outline' : 'primary'} onClick={toggleStatus} className="w-full justify-center">
                {event.status === EventStatus.COMPLETED ? 'Reabrir Item' : 'Marcar como Concluído'}
             </Button>
        )}

        {/* Metadata */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
            <div className="p-3 bg-slate-50 rounded border border-slate-100">
                <p className="text-xs font-semibold text-slate-500 uppercase mb-1">Processo Relacionado</p>
                {relatedCase ? (
                    <p className="font-medium text-blue-700 truncate">{relatedCase.title}</p>
                ) : (
                    <p className="text-slate-400 italic">Nenhum processo vinculado</p>
                )}
            </div>
            <div className="p-3 bg-slate-50 rounded border border-slate-100">
                <p className="text-xs font-semibold text-slate-500 uppercase mb-1">Responsáveis</p>
                <div className="flex flex-wrap gap-1">
                    {assignedUsers.map(u => (
                        <span key={u.id} className="flex items-center text-slate-700 bg-white px-2 py-0.5 rounded shadow-sm text-xs">
                           <img src={u.avatar} className="w-4 h-4 rounded-full mr-1"/> {u.name.split(' ')[0]}
                        </span>
                    ))}
                </div>
            </div>
        </div>

        {/* Description */}
        <div>
            <p className="text-sm font-semibold text-slate-700">Descrição</p>
            <p className="text-slate-600 text-sm mt-1">{event.description || "Sem descrição."}</p>
        </div>

        {/* Chat Section */}
        <div className="border-t border-slate-200 pt-4">
            <h4 className="text-sm font-bold text-slate-800 mb-2 flex items-center">
                <MessageSquare size={16} className="mr-2"/> Chat & Observações
            </h4>

            <div className="bg-slate-50 border border-slate-200 rounded-lg p-3 h-48 overflow-y-auto mb-3 space-y-3 scrollbar-thin">
                {event.chatMessages.length === 0 ? (
                    <p className="text-center text-xs text-slate-400 mt-16">Nenhuma mensagem ainda.</p>
                ) : (
                    event.chatMessages.map(msg => {
                        const isMe = msg.userId === currentUser.id;
                        const user = users.find(u => u.id === msg.userId);
                        return (
                            <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                <div className={`max-w-[80%] rounded-lg p-2 text-sm ${isMe ? 'bg-blue-600 text-white' : 'bg-white border border-slate-200 text-slate-800'}`}>
                                    <div className="flex items-center gap-2 mb-1 opacity-75">
                                        <span className="text-xs font-bold">{user?.name}</span>
                                        <span className="text-[10px]">{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                    </div>
                                    <p>{msg.text}</p>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>

            <div className="flex gap-2">
                <input 
                    type="text" 
                    className="flex-1 border border-slate-300 rounded-md px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500"
                    placeholder="Digite uma mensagem..."
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                />
                <Button variant="primary" onClick={handleSendMessage} className="px-3">
                    <Send size={16} />
                </Button>
            </div>
        </div>

      </div>
    </Modal>
  );
}

