export enum UserRole {
  ADMIN = 'ADMIN',
  LAWYER = 'LAWYER',
  INTERN = 'INTERN',
}

export enum EventType {
  TASK = 'TASK',
  APPOINTMENT = 'APPOINTMENT',
}

export enum EventStatus {
  PENDING = 'PENDING',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED',
}

export enum ContactType {
  CLIENT = 'CLIENT',
  OPPOSING_PARTY = 'OPPOSING_PARTY',
}

export enum CaseStatus {
  OPEN = 'Ativo',
  IN_COURT = 'Em Juízo',
  CLOSED = 'Baixado',
  ARCHIVED = 'Arquivado',
  SUSPENDED = 'Suspenso'
}

// Interfaces
export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar: string;
  email: string;
  password?: string; // Mock password for demo
}

export interface Contact {
  id: string;
  name: string;
  type: ContactType;
  email: string;
  phone: string;
  notes?: string;
}

export interface Case {
  id: string;
  number: string;
  title: string;
  clientId: string;
  status: CaseStatus;
  description: string;
  openDate: string;
  court?: string; // Tribunal
  partes?: string; // Ex: "Empresa X (Réu) x Cliente Y (Autor)"
  responsibleId?: string;
}

export interface ChatMessage {
  id: string;
  userId: string;
  text: string;
  timestamp: string;
}

export interface CalendarEvent {
  id: string;
  title: string;
  type: EventType;
  date: string; // YYYY-MM-DD
  time?: string; // HH:MM
  description?: string;
  status: EventStatus;
  caseId?: string;
  assignedToIds: string[]; // List of user IDs
  chatMessages: ChatMessage[];
}

// Props types for navigation
export type ViewName = 'DASHBOARD' | 'AGENDA' | 'CASES' | 'CONTACTS' | 'USERS';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  User, Contact, Case, CalendarEvent, ChatMessage, UserRole, 
  EventStatus
} from '../types';
import { MOCK_USERS, MOCK_CONTACTS, MOCK_CASES, MOCK_EVENTS } from '../mockData';

interface AppContextType {
  currentUser: User | null;
  users: User[];
  contacts: Contact[];
  cases: Case[];
  events: CalendarEvent[];
  isAuthenticated: boolean;

  // Auth Actions
  login: (email: string, role: UserRole) => void;
  register: (name: string, email: string, role: UserRole) => void;
  logout: () => void;

  // Data Actions
  switchUser: (userId: string) => void; // Dev helper
  addEvent: (event: CalendarEvent) => void;
  updateEvent: (event: CalendarEvent) => void;
  updateEventDate: (eventId: string, newDate: string) => void;
  deleteEvent: (eventId: string) => void;
  addCase: (caseItem: Case) => void;
  addContact: (contact: Contact) => void;
  addChatMessage: (eventId: string, text: string) => void;

  // Permission Helpers
  canCreate: () => boolean;
  canEdit: (itemOwnerId?: string) => boolean; 
  canDelete: () => boolean;
  canViewAll: () => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [cases, setCases] = useState<Case[]>(MOCK_CASES);
  const [events, setEvents] = useState<CalendarEvent[]>(MOCK_EVENTS);

  // Auth Logic
  const login = (email: string, role: UserRole) => {
    // For prototype, we just find by email or create a temp session
    const existingUser = users.find(u => u.email === email);
    if (existingUser) {
        setCurrentUser(existingUser);
    } else {
        // Fallback for demo if typed manually
        const tempUser: User = {
            id: Date.now().toString(),
            name: email.split('@')[0],
            email: email,
            role: role,
            avatar: `https://ui-avatars.com/api/?name=${email}&background=0e1b2e&color=fff`
        };
        setCurrentUser(tempUser);
    }
    setIsAuthenticated(true);
  };

  const register = (name: string, email: string, role: UserRole) => {
      const newUser: User = {
          id: Date.now().toString(),
          name, 
          email,
          role,
          avatar: `https://ui-avatars.com/api/?name=${name.replace(' ','+')}&background=0e1b2e&color=fff`
      };
      setUsers([...users, newUser]);
      setCurrentUser(newUser);
      setIsAuthenticated(true);
  };

  const logout = () => {
      setIsAuthenticated(false);
      setCurrentUser(null);
  };

  // Permission Logic
  const canCreate = () => {
    if (!currentUser) return false;
    return currentUser.role === UserRole.ADMIN;
  };

  const canEdit = (itemOwnerId?: string) => {
    if (!currentUser) return false;
    if (currentUser.role === UserRole.ADMIN) return true;
    return false;
  };

  const canDelete = () => currentUser?.role === UserRole.ADMIN;

  const canViewAll = () => currentUser?.role === UserRole.ADMIN || currentUser?.role === UserRole.LAWYER;

  // Actions
  const switchUser = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const addEvent = (event: CalendarEvent) => {
    setEvents([...events, event]);
  };

  const updateEvent = (updatedEvent: CalendarEvent) => {
    setEvents(events.map(e => e.id === updatedEvent.id ? updatedEvent : e));
  };

  const updateEventDate = (eventId: string, newDate: string) => {
    if (currentUser?.role !== UserRole.ADMIN) return; 
    setEvents(prev => prev.map(e => e.id === eventId ? { ...e, date: newDate } : e));
  };

  const deleteEvent = (eventId: string) => {
    setEvents(prev => prev.filter(e => e.id !== eventId));
  };

  const addCase = (caseItem: Case) => {
    setCases([...cases, caseItem]);
  };

  const addContact = (contact: Contact) => {
    setContacts([...contacts, contact]);
  };

  const addChatMessage = (eventId: string, text: string) => {
    if (!currentUser) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(),
      userId: currentUser.id,
      text,
      timestamp: new Date().toISOString(),
    };

    setEvents(prev => prev.map(e => {
      if (e.id === eventId) {
        return { ...e, chatMessages: [...e.chatMessages, newMessage] };
      }
      return e;
    }));
  };

  return (
    <AppContext.Provider value={{
      currentUser,
      users,
      contacts,
      cases,
      events,
      isAuthenticated,
      login,
      register,
      logout,
      switchUser,
      addEvent,
      updateEvent,
      updateEventDate,
      deleteEvent,
      addCase,
      addContact,
      addChatMessage,
      canCreate,
      canEdit,
      canDelete,
      canViewAll,
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

