                        {event.title}
                      </p>

                      <div className="mt-2 flex items-center justify-between">
                         <div className="flex -space-x-1">
                            {event.assignedToIds.slice(0, 3).map(uid => {
                                const user = users.find(u => u.id === uid);
                                if (!user) return null;
                                return (
                                    <div key={uid} className="w-4 h-4 rounded-full bg-slate-300 ring-1 ring-white flex items-center justify-center text-[8px] overflow-hidden">
                                        {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover"/> : user.name[0]}
                                    </div>
                                );
                            })}
                         </div>
                         {event.chatMessages.length > 0 && (
                             <MessageSquare size={12} className="text-slate-400"/>
                         )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {selectedEvent && (
        <EventDetailsModal 
            event={selectedEvent} 
            isOpen={!!selectedEvent} 
            onClose={() => setSelectedEvent(null)} 
        />
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Modal, Input, Select, Button } from './ui/LayoutComponents';
import { EventType, EventStatus, CalendarEvent } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
}

export default function EventFormModal({ isOpen, onClose }: Props) {
  const { cases, users, addEvent, currentUser } = useApp();
  const [title, setTitle] = useState('');
  const [type, setType] = useState<EventType>(EventType.TASK);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [time, setTime] = useState('09:00');
  const [description, setDescription] = useState('');
  const [caseId, setCaseId] = useState('');
  const [assignedTo, setAssignedTo] = useState<string[]>(currentUser ? [currentUser.id] : []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEvent: CalendarEvent = {
      id: Date.now().toString(),
      title,
      type,
      date,
      time,
      description,
      status: EventStatus.PENDING,
      caseId: caseId || undefined,
      assignedToIds: assignedTo,
      chatMessages: []
    };
    addEvent(newEvent);
    onClose();
    // Reset fundamental fields
    setTitle('');
    setDescription('');
    setCaseId('');
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Novo Item da Agenda">
       <form onSubmit={handleSubmit} className="space-y-4">
          <Input 
            label="Título" 
            value={title} 
            onChange={e => setTitle(e.target.value)} 
            required 
            placeholder="Ex: Audiência Trabalhista"
          />

          <div className="grid grid-cols-2 gap-4">
              <Select label="Tipo" value={type} onChange={e => setType(e.target.value as EventType)}>
                  <option value={EventType.TASK}>Tarefa</option>
                  <option value={EventType.APPOINTMENT}>Compromisso</option>
              </Select>
              <Input label="Data" type="date" value={date} onChange={e => setDate(e.target.value)} required />
              <Input label="Hora" type="time" value={time} onChange={e => setTime(e.target.value)} />
          </div>

          <Select label="Vincular a Processo (Opcional)" value={caseId} onChange={e => setCaseId(e.target.value)}>
              <option value="">-- Selecione um processo --</option>
              {cases.map(c => (
                  <option key={c.id} value={c.id}>
                      {c.number} - {c.title}
                  </option>
              ))}
          </Select>

          <div className="border border-slate-200 rounded p-3 bg-slate-50">
              <label className="block text-sm font-medium text-slate-700 mb-2">Responsáveis</label>
              <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto">
                  {users.map(u => (
                      <label key={u.id} className="inline-flex items-center space-x-2 text-sm bg-white border border-slate-300 rounded px-2 py-1 cursor-pointer hover:bg-slate-100 transition-colors">
                          <input 
                            type="checkbox" 
                            className="rounded text-[#0e1b2e] focus:ring-[#0e1b2e]"
                            checked={assignedTo.includes(u.id)}
                            onChange={e => {
                                if(e.target.checked) setAssignedTo([...assignedTo, u.id]);
                                else setAssignedTo(assignedTo.filter(id => id !== u.id));
                            }}
                          />
                          <span className="truncate max-w-[120px]">{u.name}</span>
                      </label>
                  ))}
              </div>
          </div>

          <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Descrição</label>
              <textarea 
                  className="w-full border border-slate-300 rounded p-2 text-sm focus:ring-[#0e1b2e] focus:border-[#0e1b2e] outline-none" 
                  rows={3}
                  value={description}
                  onChange={e => setDescription(e.target.value)}
                  placeholder="Detalhes adicionais..."
              ></textarea>
          </div>

          <div className="flex justify-end pt-2 border-t border-slate-100">
              <Button type="submit" variant="primary">Salvar Item</Button>
          </div>
       </form>
    </Modal>
  )
}

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { CalendarEvent, EventType, EventStatus, UserRole } from '../types';
import { Card, Badge, Modal, Button, Input } from './ui/LayoutComponents';
import { ChevronLeft, ChevronRight, Clock, MessageSquare, Plus, CheckCircle, Search, Filter } from 'lucide-react';
import EventDetailsModal from './EventDetailsModal';
import EventFormModal from './EventFormModal';

const DAYS = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];

export default function Agenda() {
  const { events, currentUser, updateEventDate, canCreate, users } = useApp();
  const [currentWeekStart, setCurrentWeekStart] = useState(new Date());
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | null>(null);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const getWeekDates = (startDate: Date) => {
    const dates = [];
    const start = new Date(startDate);
    const day = start.getDay();
    const diff = start.getDate() - day + (day === 0 ? -6 : 1); 
    const monday = new Date(start.setDate(diff));

    for (let i = 0; i < 7; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      dates.push(d);
    }
    return dates;
  };

  const weekDates = getWeekDates(currentWeekStart);

  const handlePrevWeek = () => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() - 7);
    setCurrentWeekStart(newDate);
  };

  const handleNextWeek = () => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() + 7);
    setCurrentWeekStart(newDate);
  };

  const handleDragStart = (e: React.DragEvent, eventId: string) => {
    if (currentUser?.role !== UserRole.ADMIN) return; 
    e.dataTransfer.setData('eventId', eventId);
  };

  const handleDrop = (e: React.DragEvent, dateStr: string) => {
    e.preventDefault();
    if (currentUser?.role !== UserRole.ADMIN) return;
    const eventId = e.dataTransfer.getData('eventId');
    if (eventId) {
      updateEventDate(eventId, dateStr);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); 
  };

  const visibleEvents = events.filter(e => {
    // Permission filter
    let hasAccess = false;
    if (currentUser?.role === UserRole.ADMIN || currentUser?.role === UserRole.LAWYER) {
        hasAccess = true;
    } else if (currentUser?.role === UserRole.INTERN) {
        hasAccess = e.assignedToIds.includes(currentUser.id);
    }

    if (!hasAccess) return false;

    // Search term filter
    if (searchTerm) {
        return e.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
               e.description?.toLowerCase().includes(searchTerm.toLowerCase());
    }
    return true;
  });

  return (
    <div className="h-full flex flex-col bg-white rounded-lg shadow-sm border border-slate-200 overflow-hidden">

      {/* Header / Filter Bar - Inspired by image */}
      <div className="p-4 border-b border-slate-200">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
            <h2 className="text-xl font-bold text-[#0e1b2e] flex items-center gap-2">
                Compromissos e Tarefas
                <Search size={18} className="text-slate-400" />
            </h2>
            <div className="flex items-center gap-2 text-sm text-[#0e1b2e] font-medium cursor-pointer hover:underline">
                Mesa de trabalho
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-2">
             <div className="flex-1 relative">
                <input 
                    type="text" 
                    placeholder="Pesquisar em compromissos e tarefas pelos campos: descrição e envolvido"
                    className="w-full border border-slate-300 rounded-sm px-3 py-2 text-sm focus:ring-1 focus:ring-[#0e1b2e] outline-none"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
             <div className="flex gap-2">
                 <select className="border border-slate-300 rounded-sm px-3 py-2 text-sm bg-white">
                     <option>Pendente</option>
                     <option>Concluído</option>
                 </select>
                 <Button variant="primary" className="rounded-sm">Pesquisar</Button>
             </div>
        </div>

        <div className="flex items-center justify-between mt-4 pt-2 border-t border-slate-100">
             <div className="flex items-center gap-2">
                 <span className="text-sm font-bold text-slate-700">Agendas exibidas:</span>
                 <div className="bg-slate-200 rounded-full w-8 h-8 flex items-center justify-center text-xs font-bold text-slate-700" title={currentUser?.name}>
                    {currentUser?.name.substring(0,2).toUpperCase()}
                 </div>
             </div>
             <div className="flex items-center gap-2">
                 <div className="flex border border-slate-300 rounded-sm overflow-hidden">
                     <button className="px-3 py-1 text-xs bg-slate-50 hover:bg-slate-100 border-r">Hoje</button>
                     <button className="px-3 py-1 text-xs bg-slate-50 hover:bg-slate-100 border-r">Dia</button>
                     <button className="px-3 py-1 text-xs bg-slate-50 hover:bg-slate-100 border-r">Semana</button>
                     <button className="px-3 py-1 text-xs bg-white font-bold text-[#0e1b2e]">Mês</button>
                 </div>
                 {canCreate() && (
                    <Button className="rounded-sm py-1 px-3 text-xs flex items-center gap-1" onClick={() => setIsCreateModalOpen(true)}>
                        <Plus size={14} /> Adicionar
                    </Button>
                 )}
             </div>
        </div>
      </div>

      {/* Week Navigation */}
      <div className="flex items-center justify-center p-2 bg-slate-50 border-b border-slate-200">
          <Button variant="ghost" onClick={handlePrevWeek} className="p-1"><ChevronLeft size={16}/></Button>
          <span className="mx-4 text-sm font-bold text-slate-700">
            {weekDates[0].toLocaleDateString('pt-BR')} - {weekDates[6].toLocaleDateString('pt-BR')}
          </span>
          <Button variant="ghost" onClick={handleNextWeek} className="p-1"><ChevronRight size={16}/></Button>
      </div>

      {/* Calendar Grid */}
      <div className="flex-1 overflow-x-auto overflow-y-hidden bg-white">
        <div className="flex h-full min-w-[1000px]">
          {weekDates.map((date) => {
            const dateStr = date.toISOString().split('T')[0];
            const isToday = new Date().toISOString().split('T')[0] === dateStr;
            const dayEvents = visibleEvents.filter(e => e.date === dateStr);

            return (
              <div 
                key={dateStr}
                className={`flex-1 flex flex-col border-r border-slate-200 last:border-r-0 min-w-[140px] ${isToday ? 'bg-slate-50' : ''}`}
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, dateStr)}
              >
                <div className="p-2 text-right border-b border-slate-100">
                  <span className="text-xs text-slate-400 mr-2">{DAYS[date.getDay()]}</span>
                  <span className={`text-sm font-bold ${isToday ? 'text-[#0e1b2e]' : 'text-slate-600'}`}>
                    {date.getDate()}
                  </span>
                </div>

                <div className="flex-1 p-2 overflow-y-auto space-y-2">
                  {dayEvents.map(event => (
                    <div
                      key={event.id}
                      draggable={currentUser?.role === UserRole.ADMIN}
                      onDragStart={(e) => handleDragStart(e, event.id)}
                      onClick={() => setSelectedEvent(event)}
                      className={`
                        bg-white p-2 rounded shadow-sm border border-slate-200 cursor-pointer group hover:shadow-md transition-all
                        relative pl-3
                        ${event.status === EventStatus.COMPLETED ? 'opacity-60' : ''}
                      `}
                    >
                      {/* Left Border Color Indicator */}
                      <div className={`absolute left-0 top-0 bottom-0 w-1 rounded-l ${
                          event.type === EventType.APPOINTMENT ? 'bg-blue-600' : 'bg-teal-600'
                      }`}></div>

                      <div className="flex justify-between items-start">
                        <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tight">
                            {event.type === EventType.APPOINTMENT ? 'Compromisso' : 'Tarefa'}
                        </p>
                        {event.time && <span className="text-[10px] font-bold text-slate-700">{event.time}</span>}
                      </div>

                      <p className="text-xs font-bold text-[#0e1b2e] leading-snug mt-1 mb-1 line-clamp-3">
                        {event.title}
                      </p>

                      <div className="mt-2 flex items-center justify-between">
                         <div className="flex -space-x-1">
                            {event.assignedToIds.slice(0, 3).map(uid => {
                                const user = users.find(u => u.id === uid);
                                if (!user) return null;
                                return (
                                    <div key={uid} className="w-4 h-4 rounded-full bg-slate-300 ring-1 ring-white flex items-center justify-center text-[8px] overflow-hidden">
                                        {user.avatar ? <img src={user.avatar} className="w-full h-full object-cover"/> : user.name[0]}
                                    </div>
                                );
                            })}
                         </div>
                         {event.chatMessages.length > 0 && (
                             <MessageSquare size={12} className="text-slate-400"/>
                         )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {selectedEvent && (
        <EventDetailsModal 
            event={selectedEvent} 
            isOpen={!!selectedEvent} 
            onClose={() => setSelectedEvent(null)} 
        />
      )}

      {/* New Create Event Modal */}
      <EventFormModal 
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { CalendarEvent, EventType, EventStatus, UserRole } from '../types';
import { Modal, Button, Badge } from './ui/LayoutComponents';
import { Send, Clock, Calendar, CheckCircle, User as UserIcon, MessageSquare } from 'lucide-react';

interface Props {
  event: CalendarEvent;
  isOpen: boolean;
  onClose: () => void;
}

export default function EventDetailsModal({ event, isOpen, onClose }: Props) {
  const { users, cases, currentUser, addChatMessage, updateEvent, canEdit } = useApp();
  const [message, setMessage] = useState('');

  const assignedUsers = users.filter(u => event.assignedToIds.includes(u.id));
  const relatedCase = cases.find(c => c.id === event.caseId);

  const handleSendMessage = () => {
    if (!message.trim()) return;
    addChatMessage(event.id, message);
    setMessage('');
  };

  const toggleStatus = () => {
    if (!canEdit()) return;
    const newStatus = event.status === EventStatus.COMPLETED ? EventStatus.PENDING : EventStatus.COMPLETED;
    updateEvent({ ...event, status: newStatus });
  };

  const changeCase = (newCaseId: string) => {
    updateEvent({ ...event, caseId: newCaseId || undefined });
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Detalhes do Evento">
      <div className="space-y-6">

        {/* Header Info */}
        <div className="flex justify-between items-start">
           <div>
              <h3 className="text-xl font-bold text-slate-900">{event.title}</h3>
              <div className="flex items-center space-x-2 mt-1 text-sm text-slate-500">
                <span className="flex items-center"><Calendar size={14} className="mr-1"/> {new Date(event.date).toLocaleDateString()}</span>
                {event.time && <span className="flex items-center"><Clock size={14} className="mr-1"/> {event.time}</span>}
              </div>
           </div>
           <Badge variant={event.status === EventStatus.COMPLETED ? 'success' : event.type === EventType.APPOINTMENT ? 'info' : 'warning'}>
              {event.status === EventStatus.COMPLETED ? 'Concluído' : event.type === EventType.APPOINTMENT ? 'Compromisso' : 'Tarefa'}
           </Badge>
        </div>

        {/* Action Button for Status */}
        {canEdit() && (
             <Button variant={event.status === EventStatus.COMPLETED ? 'outline' : 'primary'} onClick={toggleStatus} className="w-full justify-center">
                {event.status === EventStatus.COMPLETED ? 'Reabrir Item' : 'Marcar como Concluído'}
             </Button>
        )}

        {/* Metadata */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
            <div className="p-3 bg-slate-50 rounded border border-slate-100">
                <p className="text-xs font-semibold text-slate-500 uppercase mb-1">Processo Relacionado</p>
                {canEdit() ? (
                    <select 
                        className="w-full text-xs bg-white border border-slate-300 rounded p-1.5 focus:ring-[#0e1b2e] focus:border-[#0e1b2e] outline-none"
                        value={event.caseId || ''}
                        onChange={(e) => changeCase(e.target.value)}
                    >
                        <option value="">-- Sem vínculo --</option>
                        {cases.map(c => (
                            <option key={c.id} value={c.id}>{c.number} - {c.title}</option>
                        ))}
                    </select>
                ) : (
                    relatedCase ? (
                        <p className="font-medium text-blue-700 truncate">{relatedCase.title}</p>
                    ) : (
                        <p className="text-slate-400 italic">Nenhum processo vinculado</p>
                    )
                )}
            </div>
            <div className="p-3 bg-slate-50 rounded border border-slate-100">
                <p className="text-xs font-semibold text-slate-500 uppercase mb-1">Responsáveis</p>
                <div className="flex flex-wrap gap-1">
                    {assignedUsers.map(u => (
                        <span key={u.id} className="flex items-center text-slate-700 bg-white px-2 py-0.5 rounded shadow-sm text-xs">
                           <img src={u.avatar} className="w-4 h-4 rounded-full mr-1"/> {u.name.split(' ')[0]}
                        </span>
                    ))}
                    {assignedUsers.length === 0 && <span className="text-slate-400 italic">Nenhum</span>}
                </div>
            </div>
        </div>

        {/* Description */}
        <div>
            <p className="text-sm font-semibold text-slate-700">Descrição</p>
            <p className="text-slate-600 text-sm mt-1">{event.description || "Sem descrição."}</p>
        </div>

        {/* Chat Section */}
        <div className="border-t border-slate-200 pt-4">
            <h4 className="text-sm font-bold text-slate-800 mb-2 flex items-center">
                <MessageSquare size={16} className="mr-2"/> Chat & Observações
            </h4>

            <div className="bg-slate-50 border border-slate-200 rounded-lg p-3 h-48 overflow-y-auto mb-3 space-y-3 scrollbar-thin">
                {event.chatMessages.length === 0 ? (
                    <p className="text-center text-xs text-slate-400 mt-16">Nenhuma mensagem ainda.</p>
                ) : (
                    event.chatMessages.map(msg => {
                        const isMe = msg.userId === currentUser?.id;
                        const user = users.find(u => u.id === msg.userId);
                        return (
                            <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                                <div className={`max-w-[80%] rounded-lg p-2 text-sm ${isMe ? 'bg-[#0e1b2e] text-white' : 'bg-white border border-slate-200 text-slate-800'}`}>
                                    <div className={`flex items-center gap-2 mb-1 ${isMe ? 'text-slate-300' : 'text-slate-500'}`}>
                                        <span className="text-xs font-bold">{user?.name}</span>
                                        <span className="text-[10px]">{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                    </div>
                                    <p>{msg.text}</p>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>

            <div className="flex gap-2">
                <input 
                    type="text" 
                    className="flex-1 border border-slate-300 rounded-md px-3 py-2 text-sm focus:ring-[#0e1b2e] focus:border-[#0e1b2e] outline-none"
                    placeholder="Digite uma mensagem..."
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                />
                <Button variant="primary" onClick={handleSendMessage} className="px-3">
                    <Send size={16} />
                </Button>
            </div>
        </div>

      </div>
    </Modal>
  );
}

