import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  User, Contact, Case, CalendarEvent, ChatMessage, UserRole, 
  EventStatus, CaseDocument, CaseStatus, EventType
} from '../types';
import { supabase } from '../supabaseClient';

interface AppContextType {
  currentUser: User | null;
  users: User[];
  contacts: Contact[];
  cases: Case[];
  events: CalendarEvent[];
  isAuthenticated: boolean;
  isLoading: boolean;

  // Auth Actions
  login: (email: string, role: UserRole) => Promise<void>;
  register: (name: string, email: string, role: UserRole) => Promise<void>;
  logout: () => void;

  // Data Actions
  switchUser: (userId: string) => void;
  addEvent: (event: CalendarEvent) => void;
  updateEvent: (event: CalendarEvent) => void;
  updateEventDate: (eventId: string, newDate: string) => void;
  deleteEvent: (eventId: string) => void;
  addCase: (caseItem: Case) => void;
  addContact: (contact: Contact) => void;
  addChatMessage: (eventId: string, text: string) => void;
  addCaseDocument: (caseId: string, file: File) => void;

  // Permission Helpers
  canCreate: () => boolean;
  canEdit: (itemOwnerId?: string) => boolean; 
  canDelete: () => boolean;
  canViewAll: () => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [cases, setCases] = useState<Case[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // --- Initial Data Fetching ---
  const fetchData = async () => {
    try {
        // 1. Fetch Users (Profiles)
        const { data: profilesData } = await supabase.from('profiles').select('*');
        if (profilesData) {
            setUsers(profilesData.map((p: any) => ({
                id: p.id,
                name: p.name,
                email: p.email,
                role: p.role,
                avatar: p.avatar || `https://ui-avatars.com/api/?name=${p.name}&background=0e1b2e&color=fff`
            })));
        }

        // 2. Fetch Contacts
        const { data: contactsData } = await supabase.from('contacts').select('*');
        if (contactsData) setContacts(contactsData);

        // 3. Fetch Cases & Documents
        const { data: casesData } = await supabase.from('cases').select(`
            *,
            case_documents (*)
        `);

        if (casesData) {
            const mappedCases = casesData.map((c: any) => ({
                id: c.id,
                number: c.number,
                title: c.title,
                clientId: c.client_id,
                status: c.status,
                description: c.description,
                openDate: c.open_date,
                court: c.court,
                partes: c.partes,
                documents: c.case_documents ? c.case_documents.map((d: any) => ({
                    id: d.id,
                    name: d.name,
                    type: d.type,
                    size: d.size,
                    uploadDate: d.upload_date,
                    uploadedBy: d.uploaded_by,
                    url: d.url
                })) : []
            }));
            setCases(mappedCases);
        }

        // 4. Fetch Events & Chat Messages
        const { data: eventsData } = await supabase.from('events').select(`
            *,
            chat_messages (*)
        `);

        if (eventsData) {
             const mappedEvents = eventsData.map((e: any) => ({
                id: e.id,
                title: e.title,
                type: e.type,
                date: e.date,
                time: e.time,
                description: e.description,
                status: e.status,
                caseId: e.case_id,
                assignedToIds: e.assigned_to || [], // Assumes DB has assigned_to as text[]
                chatMessages: e.chat_messages ? e.chat_messages.map((m: any) => ({
                    id: m.id,
                    userId: m.user_id,
                    text: m.text,
                    timestamp: m.timestamp
                })) : []
             }));
             setEvents(mappedEvents);
        }

    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        setIsLoading(false);
    }
  };

  // --- Auth Listener ---
  useEffect(() => {
    const checkUser = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
            // Get profile details
            const { data: profile } = await supabase
                .from('profiles')
                .select('*')
                .eq('id', session.user.id)
                .single();

            if (profile) {
                const userObj: User = {
                    id: profile.id,
                    name: profile.name,
                    email: profile.email,
                    role: profile.role,
                    avatar: profile.avatar || `https://ui-avatars.com/api/?name=${profile.name}&background=0e1b2e&color=fff`
                };
                setCurrentUser(userObj);
                setIsAuthenticated(true);
                fetchData();
            }
        } else {
            setIsLoading(false);
        }
    };

    checkUser();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (_event, session) => {
        if (session) {
             // Logic repeated to ensure profile load on login
             const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
             if (profile) {
                setCurrentUser({
                    id: profile.id,
                    name: profile.name,
                    email: profile.email,
                    role: profile.role,
                    avatar: profile.avatar
                });
                setIsAuthenticated(true);
                fetchData();
             }
        } else {
            setCurrentUser(null);
            setIsAuthenticated(false);
            setEvents([]);
            setCases([]);
            setContacts([]);
        }
    });

    return () => subscription.unsubscribe();
  }, []);

  // --- Auth Actions ---

  const login = async (email: string, role: UserRole) => { // Role ignored in real auth, derived from DB
    try {
        // NOTE: For this demo without password input, we are using the email as password or a default
        // In a real scenario, the Auth component would pass the password.
        // Assuming a default password for the demo users '123456'
        const { error } = await supabase.auth.signInWithPassword({
            email,
            password: 'password123' // Hardcoded for ease of demo, user should input
        });
        if (error) throw error;
    } catch (error) {
        alert("Erro ao logar. (Demo: use a senha 'password123')");
        console.error(error);
    }
  };

  const register = async (name: string, email: string, role: UserRole) => {
      try {
        // 1. Create Auth User
        const { data: authData, error: authError } = await supabase.auth.signUp({
            email,
            password: 'password123', // Hardcoded for demo
        });

        if (authError) throw authError;

        if (authData.user) {
            // 2. Create Profile Entry
            const { error: profileError } = await supabase.from('profiles').insert([{
                id: authData.user.id,
                name,
                email,
                role,
                avatar: `https://ui-avatars.com/api/?name=${name.replace(' ','+')}&background=0e1b2e&color=fff`
            }]);

            if (profileError) throw profileError;

            alert("Usuário registrado! Faça login.");
        }
      } catch (error: any) {
          alert("Erro ao registrar: " + error.message);
      }
  };

  const logout = async () => {
      await supabase.auth.signOut();
  };

  // --- Data Actions ---

  const switchUser = (userId: string) => {
    // Only for dev/admin in this context, effectively a 'become user'
    // With real auth, this isn't really possible without re-logging
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const addEvent = async (event: CalendarEvent) => {
    // Optimistic Update
    setEvents([...events, event]);

    const { data, error } = await supabase.from('events').insert([{
        title: event.title,
        type: event.type,
        date: event.date,
        time: event.time,
        description: event.description,
        status: event.status,
        case_id: event.caseId,
        assigned_to: event.assignedToIds
    }]).select().single();

    if (data) {
        // Replace temp ID with real ID
        setEvents(prev => prev.map(e => e.id === event.id ? { ...e, id: data.id, chatMessages: [] } : e));
    } else if (error) {
        console.error(error);
        // Revert optimistic
        setEvents(prev => prev.filter(e => e.id !== event.id));
    }
  };

  const updateEvent = async (updatedEvent: CalendarEvent) => {
    setEvents(events.map(e => e.id === updatedEvent.id ? updatedEvent : e));

    await supabase.from('events').update({
        title: updatedEvent.title,
        type: updatedEvent.type,
        date: updatedEvent.date,
        time: updatedEvent.time,
        description: updatedEvent.description,
        status: updatedEvent.status,
        case_id: updatedEvent.caseId,
        assigned_to: updatedEvent.assignedToIds
    }).eq('id', updatedEvent.id);
  };

  const updateEventDate = async (eventId: string, newDate: string) => {
    if (currentUser?.role !== UserRole.ADMIN) return; 
    setEvents(prev => prev.map(e => e.id === eventId ? { ...e, date: newDate } : e));

    await supabase.from('events').update({ date: newDate }).eq('id', eventId);
  };

  const deleteEvent = async (eventId: string) => {
    setEvents(prev => prev.filter(e => e.id !== eventId));
    await supabase.from('events').delete().eq('id', eventId);
  };

  const addCase = async (caseItem: Case) => {
    // Optimistic
    const newCase = { ...caseItem, documents: [] };
    setCases([...cases, newCase]);

    const { data, error } = await supabase.from('cases').insert([{
        number: caseItem.number,
        title: caseItem.title,
        client_id: caseItem.clientId,
        status: caseItem.status,
        court: caseItem.court,
        partes: caseItem.partes,
        description: caseItem.description,
        open_date: caseItem.openDate
    }]).select().single();

     if (data) {
        setCases(prev => prev.map(c => c.id === caseItem.id ? { ...c, id: data.id } : c));
    }
  };

  const addContact = async (contact: Contact) => {
    setContacts([...contacts, contact]);

    const { data } = await supabase.from('contacts').insert([{
        name: contact.name,
        type: contact.type,
        email: contact.email,
        phone: contact.phone,
        notes: contact.notes
    }]).select().single();

    if (data) {
         setContacts(prev => prev.map(c => c.id === contact.id ? { ...c, id: data.id } : c));
    }
  };

  const addChatMessage = async (eventId: string, text: string) => {
    if (!currentUser) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(), // Temp ID
      userId: currentUser.id,
      text,
      timestamp: new Date().toISOString(),
    };

    setEvents(prev => prev.map(e => {
      if (e.id === eventId) {
        return { ...e, chatMessages: [...e.chatMessages, newMessage] };
      }
      return e;
    }));

    const { data } = await supabase.from('chat_messages').insert([{
        event_id: eventId,
        user_id: currentUser.id,
        text: text,
        timestamp: newMessage.timestamp
    }]).select().single();

    if (data) {
        // Update ID if necessary
    }
  };

  const addCaseDocument = async (caseId: string, file: File) => {
    if (!currentUser) return;

    // In a real app, upload to Supabase Storage first, then get URL.
    // Here we just insert metadata record.

    const newDoc: CaseDocument = {
        id: Date.now().toString(),
        name: file.name,
        type: file.type || 'application/pdf',
        size: (file.size / 1024).toFixed(2) + ' KB',
        uploadDate: new Date().toISOString(),
        uploadedBy: currentUser.name,
        url: '#' 
    };

    setCases(prev => prev.map(c => {
        if (c.id === caseId) {
            return { ...c, documents: [...(c.documents || []), newDoc] };
        }
        return c;
    }));

    await supabase.from('case_documents').insert([{
        case_id: caseId,
        name: newDoc.name,
        type: newDoc.type,
        size: newDoc.size,
        upload_date: newDoc.uploadDate,
        uploaded_by: newDoc.uploadedBy,
        url: newDoc.url
    }]);
  };

  // --- Permissions ---
  const canCreate = () => {
    if (!currentUser) return false;
    return currentUser.role === UserRole.ADMIN;
  };

  const canEdit = (itemOwnerId?: string) => {
    if (!currentUser) return false;
    if (currentUser.role === UserRole.ADMIN) return true;
    return false;
  };

  const canDelete = () => currentUser?.role === UserRole.ADMIN;

  const canViewAll = () => currentUser?.role === UserRole.ADMIN || currentUser?.role === UserRole.LAWYER;

  return (
    <AppContext.Provider value={{
      currentUser,
      users,
      contacts,
      cases,
      events,
      isAuthenticated,
      isLoading,
      login,
      register,
      logout,
      switchUser,
      addEvent,
      updateEvent,
      updateEventDate,
      deleteEvent,
      addCase,
      addContact,
      addChatMessage,
      addCaseDocument,
      canCreate,
      canEdit,
      canDelete,
      canViewAll,
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

