                 profile = newProfile;
            }

            if (profile) {
                const userObj: User = {
                    id: profile.id,
                    name: profile.name,
                    email: profile.email,
                    role: profile.role,
                    avatar: profile.avatar || `https://ui-avatars.com/api/?name=${profile.name}&background=0e1b2e&color=fff`
                };
                setCurrentUser(userObj);
                setIsAuthenticated(true);
                fetchData();
            } else {
                setIsLoading(false);
            }
        } else {
            setIsLoading(false);
        }
    };

    checkUser();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (session) {
             if (event === 'SIGNED_IN') {
                 // Logic repeated to ensure consistency
                 let { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();

                 // Retry creation if missing (redundancy for direct login events)
                 if (!profile && session.user.user_metadata?.name) {
                     const { name, role, avatar } = session.user.user_metadata;
                     await supabase.from('profiles').insert([{
                        id: session.user.id,
                        name,
                        email: session.user.email,
                        role: role || UserRole.INTERN,
                        avatar: avatar
                     }]);
                     const { data: newProfile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
                     profile = newProfile;
