        status: updatedEvent.status,
        case_id: updatedEvent.caseId,
        assigned_to: updatedEvent.assignedToIds
    }).eq('id', updatedEvent.id);
  };

  const updateEventDate = async (eventId: string, newDate: string) => {
    if (currentUser?.role !== UserRole.ADMIN) return; 
    setEvents(prev => prev.map(e => e.id === eventId ? { ...e, date: newDate } : e));

    await supabase.from('events').update({ date: newDate }).eq('id', eventId);
  };

  const deleteEvent = async (eventId: string) => {
    setEvents(prev => prev.filter(e => e.id !== eventId));
    await supabase.from('events').delete().eq('id', eventId);
  };

  const addCase = async (caseItem: Case) => {
    // Optimistic
    const newCase = { ...caseItem, documents: [] };
    setCases([...cases, newCase]);

    const { data, error } = await supabase.from('cases').insert([{
        number: caseItem.number,
        title: caseItem.title,
        client_id: caseItem.clientId,
        status: caseItem.status,
        court: caseItem.court,
        partes: caseItem.partes,
        description: caseItem.description,
        open_date: caseItem.openDate
    }]).select().single();

     if (data) {
        setCases(prev => prev.map(c => c.id === caseItem.id ? { ...c, id: data.id } : c));
    }
  };

  const addContact = async (contact: Contact) => {
    setContacts([...contacts, contact]);

    const { data } = await supabase.from('contacts').insert([{
        name: contact.name,
        type: contact.type,
        email: contact.email,
        phone: contact.phone,
        notes: contact.notes
    }]).select().single();

    if (data) {
         setContacts(prev => prev.map(c => c.id === contact.id ? { ...c, id: data.id } : c));
    }
  };

  const addChatMessage = async (eventId: string, text: string) => {
    if (!currentUser) return;
    const newMessage: ChatMessage = {
      id: Date.now().toString(), // Temp ID
      userId: currentUser.id,
      text,
      timestamp: new Date().toISOString(),
    };

    setEvents(prev => prev.map(e => {
      if (e.id === eventId) {
        return { ...e, chatMessages: [...e.chatMessages, newMessage] };
      }
      return e;
    }));

    const { data } = await supabase.from('chat_messages').insert([{
        event_id: eventId,
        user_id: currentUser.id,
        text: text,
        timestamp: newMessage.timestamp
    }]).select().single();

    if (data) {
        // Update ID if necessary
    }
  };

  const addCaseDocument = async (caseId: string, file: File) => {
    if (!currentUser) return;

    // In a real app, upload to Supabase Storage first, then get URL.
    // Here we just insert metadata record.

    const newDoc: CaseDocument = {
        id: Date.now().toString(),
        name: file.name,
        type: file.type || 'application/pdf',
        size: (file.size / 1024).toFixed(2) + ' KB',
        uploadDate: new Date().toISOString(),
        uploadedBy: currentUser.name,
        url: '#' 
    };

    setCases(prev => prev.map(c => {
        if (c.id === caseId) {
            return { ...c, documents: [...(c.documents || []), newDoc] };
        }
        return c;
    }));

    await supabase.from('case_documents').insert([{
        case_id: caseId,
        name: newDoc.name,
        type: newDoc.type,
        size: newDoc.size,
        upload_date: newDoc.uploadDate,
        uploaded_by: newDoc.uploadedBy,
        url: newDoc.url
    }]);
  };

  // --- Permissions ---
  const canCreate = () => {
    if (!currentUser) return false;
    return currentUser.role === UserRole.ADMIN;
  };

  const canEdit = (itemOwnerId?: string) => {
    if (!currentUser) return false;
    if (currentUser.role === UserRole.ADMIN) return true;
    return false;
  };

  const canDelete = () => currentUser?.role === UserRole.ADMIN;

  const canViewAll = () => currentUser?.role === UserRole.ADMIN || currentUser?.role === UserRole.LAWYER;

  return (
    <AppContext.Provider value={{
      currentUser,
      users,
      contacts,
      cases,
      events,
      isAuthenticated,
      isLoading,
      login,
      register,
      logout,
      switchUser,
      addEvent,
      updateEvent,
      updateEventDate,
      deleteEvent,
      addCase,
      addContact,
      addChatMessage,
      addCaseDocument,
      canCreate,
      canEdit,
      canDelete,
      canViewAll,
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

