import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  User, Contact, Case, CalendarEvent, ChatMessage, UserRole, 
  EventStatus, CaseDocument, CaseStatus, EventType
} from '../types';
import { supabase } from '../supabaseClient';

interface AppContextType {
  currentUser: User | null;
  users: User[];
  contacts: Contact[];
  cases: Case[];
  events: CalendarEvent[];
  isAuthenticated: boolean;
  isLoading: boolean;

  // Auth Actions
  login: (email: string, password: string) => Promise<void>;
  register: (name: string, email: string, password: string, role: UserRole) => Promise<void>;
  logout: () => void;

  // Data Actions
  switchUser: (userId: string) => void;
  addEvent: (event: CalendarEvent) => void;
  updateEvent: (event: CalendarEvent) => void;
  updateEventDate: (eventId: string, newDate: string) => void;
  deleteEvent: (eventId: string) => void;
  addCase: (caseItem: Case) => void;
  addContact: (contact: Contact) => void;
  addChatMessage: (eventId: string, text: string) => void;
  addCaseDocument: (caseId: string, file: File) => void;

  // Permission Helpers
  canCreate: () => boolean;
  canEdit: (itemOwnerId?: string) => boolean; 
  canDelete: () => boolean;
  canViewAll: () => boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [cases, setCases] = useState<Case[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // --- Initial Data Fetching ---
  const fetchData = async () => {
    try {
        // 1. Fetch Users (From 'users' table based on SQL)
        const { data: usersData } = await supabase.from('users').select('*');
        if (usersData) {
            setUsers(usersData.map((p: any) => ({
                id: p.id, // This is the Profile UUID, not Auth ID
                name: p.name,
                email: p.email,
                role: p.role,
                avatar: p.avatar || `https://ui-avatars.com/api/?name=${p.name}&background=0e1b2e&color=fff`
            })));
        }

        // 2. Fetch Contacts
        const { data: contactsData } = await supabase.from('contacts').select('*');
        if (contactsData) setContacts(contactsData);

        // 3. Fetch Cases & Documents
        const { data: casesData } = await supabase.from('cases').select(`
            *,
            case_documents (*)
        `);

        if (casesData) {
            const mappedCases = casesData.map((c: any) => ({
                id: c.id,
                number: c.number,
                title: c.title,
                clientId: c.client_id,
                status: c.status,
                description: c.description,
                openDate: c.open_date,
                court: c.court,
                partes: c.partes,
                documents: c.case_documents ? c.case_documents.map((d: any) => ({
                    id: d.id,
                    name: d.name,
                    type: d.type,
                    size: d.size,
                    uploadDate: d.upload_date,
                    uploadedBy: d.uploaded_by,
                    url: d.url
                })) : []
            }));
            setCases(mappedCases);
        }

        // 4. Fetch Events (calendar_events) & Join Assignments/Chats
        // Using explicit join for event_assignments
        const { data: eventsData, error } = await supabase.from('calendar_events').select(`
            *,
            event_assignments (user_id),
            chat_messages (*)
        `);

        if (error) console.error("Error fetching events:", error);

        if (eventsData) {
             const mappedEvents = eventsData.map((e: any) => ({
                id: e.id,
                title: e.title,
                type: e.type,
                date: e.event_date, // Mapped from SQL event_date
                time: e.event_time ? e.event_time.slice(0, 5) : '', // Mapped from SQL event_time
                description: e.description,
                status: e.status,
                caseId: e.case_id,
                // Flatten the nested array of objects [{user_id: '...'}, {user_id: '...'}]
                assignedToIds: e.event_assignments ? e.event_assignments.map((ea: any) => ea.user_id) : [], 
                chatMessages: e.chat_messages ? e.chat_messages.map((m: any) => ({
                    id: m.id,
                    userId: m.user_id,
                    text: m.text,
                    timestamp: m.timestamp
                })) : []
             }));
             setEvents(mappedEvents);
        }

    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        setIsLoading(false);
    }
  };

  // --- Auth Listener ---
  useEffect(() => {
    const checkUser = async () => {
        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
            // Find user in 'users' table using auth_user_id
            let { data: profile } = await supabase
                .from('users')
                .select('*')
                .eq('auth_user_id', session.user.id)
                .single();

            // RECOVERY: Attempt creation if missing (will fail if RLS blocks, but we try)
            if (!profile && session.user.user_metadata?.name) {
                 const { name, role, avatar } = session.user.user_metadata;
                 // Insert into 'users' with auth_user_id
                 await supabase.from('users').insert([{
                    auth_user_id: session.user.id,
                    name,
                    email: session.user.email,
                    role: role || UserRole.INTERN,
                    avatar: avatar
                 }]);

                 const { data: newProfile } = await supabase.from('users').select('*').eq('auth_user_id', session.user.id).single();
                 profile = newProfile;
            }

            if (profile) {
                const userObj: User = {
                    id: profile.id, // Use the Table ID (UUID), not Auth ID
                    name: profile.name,
                    email: profile.email,
                    role: profile.role,
                    avatar: profile.avatar
                };
                setCurrentUser(userObj);
                setIsAuthenticated(true);
                fetchData();
            } else {
                console.warn("User authenticated but no profile found in 'users' table.");
                setIsLoading(false);
            }
        } else {
            setIsLoading(false);
        }
    };

    checkUser();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (session) {
             if (event === 'SIGNED_IN') {
                 let { data: profile } = await supabase.from('users').select('*').eq('auth_user_id', session.user.id).single();

                 if (profile) {
                    setCurrentUser({
                        id: profile.id,
                        name: profile.name,
                        email: profile.email,
                        role: profile.role,
                        avatar: profile.avatar
                    });
                    setIsAuthenticated(true);
                    fetchData();
                 }
             }
        } else {
            setCurrentUser(null);
            setIsAuthenticated(false);
            setEvents([]);
            setCases([]);
            setContacts([]);
        }
    });

    return () => subscription.unsubscribe();
  }, []);

  // --- Auth Actions ---

  const login = async (email: string, password: string) => { 
    setIsLoading(true);
    try {
        const { error } = await supabase.auth.signInWithPassword({
            email,
            password
        });

        if (error) throw error;
    } catch (error: any) {
        alert("Erro ao logar: " + (error.message || error));
        console.error(error);
        setIsLoading(false);
    }
  };

  const register = async (name: string, email: string, password: string, role: UserRole) => {
      setIsLoading(true);
      try {
        const avatarUrl = `https://ui-avatars.com/api/?name=${name.replace(' ','+')}&background=0e1b2e&color=fff`;

        // 1. Create Auth User
        const { data: authData, error: authError } = await supabase.auth.signUp({
            email,
            password, 
            options: {
                data: { name, role, avatar: avatarUrl }
            }
        });

        if (authError) throw authError;

        if (authData.user) {
            // 2. Try Insert into 'users' table
            // IMPORTANT: If RLS 'Only admins can insert users' is active, this WILL FAIL for new users.
            const { error: profileError } = await supabase.from('users').insert([{
                auth_user_id: authData.user.id, // Link to Auth
                name,
                email,
                role,
                avatar: avatarUrl
            }]);

            if (profileError) {
                console.error("Profile creation error:", profileError);
                if (profileError.code === '42501') { // Permission denied
                    alert("Usuário de autenticação criado, mas o perfil no banco falhou devido a permissões.\n\nIMPORTANTE: Seu banco está configurado para permitir criação de usuários APENAS por Admins. Se este é o primeiro usuário, altere a política RLS no Supabase ou insira manualmente na tabela 'users'.");
                }
            } else {
                if (authData.session) {
                    alert("Usuário registrado com sucesso! Você já está logado.");
                } else {
                    alert("Cadastro realizado! Verifique seu e-mail.");
                }
            }
        }
      } catch (error: any) {
          alert("Erro ao registrar: " + error.message);
      } finally {
        setIsLoading(false);
      }
  };

  const logout = async () => {
      await supabase.auth.signOut();
  };

  // --- Data Actions ---

  const switchUser = (userId: string) => {
    // Dev helper
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const addEvent = async (event: CalendarEvent) => {
    // Optimistic Update (Partial, complex due to relations)
    setEvents(prev => [...prev, event]);

    // 1. Insert Event
    const { data: eventData, error: eventError } = await supabase.from('calendar_events').insert([{
        title: event.title,
        type: event.type,
        event_date: event.date,
        event_time: event.time,
        description: event.description,
        status: event.status,
        case_id: event.caseId
    }]).select().single();

    if (eventError) {
        console.error(eventError);
        setEvents(prev => prev.filter(e => e.id !== event.id)); // Revert
        return;
    }

    if (eventData) {
        // 2. Insert Assignments
        if (event.assignedToIds.length > 0) {
            const assignments = event.assignedToIds.map(uid => ({
                event_id: eventData.id,
                user_id: uid
            }));
            await supabase.from('event_assignments').insert(assignments);
        }

        // Refresh Data to get proper joins
        // For performance we could just patch state, but fetching ensures consistency with DB IDs
        const { data: refreshedEvent } = await supabase.from('calendar_events').select(`
            *,
            event_assignments (user_id),
            chat_messages (*)
        `).eq('id', eventData.id).single();

        if (refreshedEvent) {
             const mapped: CalendarEvent = {
                id: refreshedEvent.id,
                title: refreshedEvent.title,
                type: refreshedEvent.type,
                date: refreshedEvent.event_date,
                time: refreshedEvent.event_time?.slice(0,5),
                description: refreshedEvent.description,
                status: refreshedEvent.status,
                caseId: refreshedEvent.case_id,
                assignedToIds: refreshedEvent.event_assignments ? refreshedEvent.event_assignments.map((ea: any) => ea.user_id) : [],
                chatMessages: []
             };
             setEvents(prev => prev.map(e => e.id === event.id ? mapped : e));
        }
    }
  };

  const updateEvent = async (updatedEvent: CalendarEvent) => {
    setEvents(events.map(e => e.id === updatedEvent.id ? updatedEvent : e));

    // 1. Update basic fields
    await supabase.from('calendar_events').update({
        title: updatedEvent.title,
        type: updatedEvent.type,
        event_date: updatedEvent.date,
        event_time: updatedEvent.time,
        description: updatedEvent.description,
        status: updatedEvent.status,
        case_id: updatedEvent.caseId
    }).eq('id', updatedEvent.id);

    // 2. Sync Assignments (Delete all and re-insert is simplest strategy for this scale)
    await supabase.from('event_assignments').delete().eq('event_id', updatedEvent.id);
    if (updatedEvent.assignedToIds.length > 0) {
        const assignments = updatedEvent.assignedToIds.map(uid => ({
            event_id: updatedEvent.id,
            user_id: uid
        }));
        await supabase.from('event_assignments').insert(assignments);
    }
  };

  const updateEventDate = async (eventId: string, newDate: string) => {
    if (currentUser?.role !== UserRole.ADMIN) return; 
    setEvents(prev => prev.map(e => e.id === eventId ? { ...e, date: newDate } : e));
    await supabase.from('calendar_events').update({ event_date: newDate }).eq('id', eventId);
  };

  const deleteEvent = async (eventId: string) => {
    setEvents(prev => prev.filter(e => e.id !== eventId));
    await supabase.from('calendar_events').delete().eq('id', eventId);
  };

  const addCase = async (caseItem: Case) => {
    const newCase = { ...caseItem, documents: [] };
    setCases([...cases, newCase]);

    const { data, error } = await supabase.from('cases').insert([{
        number: caseItem.number,
        title: caseItem.title,
        client_id: caseItem.clientId,
        status: caseItem.status,
        court: caseItem.court,
        partes: caseItem.partes,
        description: caseItem.description,
        open_date: caseItem.openDate
    }]).select().single();

    if (error) {
        console.error(error);
        return;
    }

     if (data) {
        setCases(prev => prev.map(c => c.id === caseItem.id ? { ...c, id: data.id } : c));
    }
  };

  const addContact = async (contact: Contact) => {
    setContacts([...contacts, contact]);

    const { data } = await supabase.from('contacts').insert([{
        name: contact.name,
        type: contact.type,
        email: contact.email,
        phone: contact.phone,
        notes: contact.notes
    }]).select().single();

    if (data) {
         setContacts(prev => prev.map(c => c.id === contact.id ? { ...c, id: data.id } : c));
    }
  };

  const addChatMessage = async (eventId: string, text: string) => {
    if (!currentUser) return;
    const tempId = Date.now().toString();
    const newMessage: ChatMessage = {
      id: tempId,
      userId: currentUser.id,
      text,
      timestamp: new Date().toISOString(),
    };

    setEvents(prev => prev.map(e => {
      if (e.id === eventId) {
        return { ...e, chatMessages: [...e.chatMessages, newMessage] };
      }
      return e;
    }));

    const { data } = await supabase.from('chat_messages').insert([{
        event_id: eventId,
        user_id: currentUser.id, // Current User ID (UUID from users table)
        text: text,
        timestamp: newMessage.timestamp
    }]).select().single();

    if (data) {
        setEvents(prev => prev.map(e => {
            if (e.id === eventId) {
                return { 
                    ...e, 
                    chatMessages: e.chatMessages.map(m => m.id === tempId ? { ...m, id: data.id } : m)
                };
            }
            return e;
        }));
    }
  };

  const addCaseDocument = async (caseId: string, file: File) => {
    if (!currentUser) return;

    // In a real app, upload to Supabase Storage first.

    const newDoc: CaseDocument = {
        id: Date.now().toString(),
        name: file.name,
        type: file.type || 'application/pdf',
        size: (file.size / 1024).toFixed(2) + ' KB',
        uploadDate: new Date().toISOString(),
        uploadedBy: currentUser.name,
        url: '#' 
    };

    setCases(prev => prev.map(c => {
        if (c.id === caseId) {
            return { ...c, documents: [...(c.documents || []), newDoc] };
        }
        return c;
    }));

    await supabase.from('case_documents').insert([{
        case_id: caseId,
        name: newDoc.name,
        type: newDoc.type,
        size: newDoc.size,
        upload_date: newDoc.uploadDate,
        uploaded_by: currentUser.id, // Use ID
        url: newDoc.url
    }]);
  };

  // --- Permissions ---
  const canCreate = () => {
    if (!currentUser) return false;
    return currentUser.role === UserRole.ADMIN;
  };

  const canEdit = (itemOwnerId?: string) => {
    if (!currentUser) return false;
    if (currentUser.role === UserRole.ADMIN) return true;
    return false;
  };

  const canDelete = () => currentUser?.role === UserRole.ADMIN;

  const canViewAll = () => currentUser?.role === UserRole.ADMIN || currentUser?.role === UserRole.LAWYER;

  return (
    <AppContext.Provider value={{
