// =====================================================
// EXEMPLO DE AUTENTICAÇÃO CUSTOMIZADA COM SUPABASE
// =====================================================

import { createClient } from '@supabase/supabase-js';
import bcrypt from 'bcryptjs'; // Instalar: npm install bcryptjs

const supabase = createClient(
  process.env.REACT_APP_SUPABASE_URL!,
  process.env.REACT_APP_SUPABASE_ANON_KEY!
);

// =====================================================
// REGISTRO DE NOVO USUÁRIO
// =====================================================

export async function registerUser(
  name: string,
  email: string,
  password: string,
  role: 'ADMIN' | 'LAWYER' | 'INTERN' = 'INTERN'
) {
  try {
    // 1. Criar hash da senha
    const passwordHash = await bcrypt.hash(password, 10);

    // 2. Inserir usuário no banco
    const { data, error } = await supabase
      .from('users')
      .insert([
        {
          name,
          email,
          password: passwordHash,
          role,
          avatar: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=334155&color=fff`
        }
      ])
      .select()
      .single();

    if (error) throw error;

    // 3. Salvar sessão no localStorage
    localStorage.setItem('currentUser', JSON.stringify(data));

    return { success: true, user: data };
  } catch (error: any) {
    console.error('Erro ao registrar:', error);
    return { success: false, error: error.message };
  }
}

// =====================================================
// LOGIN
// =====================================================

export async function login(email: string, password: string) {
  try {
    // 1. Buscar usuário por email
    const { data: user, error } = await supabase
      .from('users')
      .select('*')
      .eq('email', email)
      .single();

    if (error || !user) {
      return { success: false, error: 'Email ou senha incorretos' };
    }

    // 2. Verificar senha
    const passwordMatch = await bcrypt.compare(password, user.password);

    if (!passwordMatch) {
      return { success: false, error: 'Email ou senha incorretos' };
    }

    // 3. Remover senha do objeto antes de salvar
    const { password: _, ...userWithoutPassword } = user;

    // 4. Salvar sessão no localStorage
    localStorage.setItem('currentUser', JSON.stringify(userWithoutPassword));

    return { success: true, user: userWithoutPassword };
  } catch (error: any) {
    console.error('Erro ao fazer login:', error);
    return { success: false, error: error.message };
  }
}

// =====================================================
// LOGOUT
// =====================================================

export function logout() {
  localStorage.removeItem('currentUser');
  window.location.href = '/login';
}

// =====================================================
// OBTER USUÁRIO ATUAL
// =====================================================

export function getCurrentUser() {
  const userStr = localStorage.getItem('currentUser');
  if (!userStr) return null;

  try {
    return JSON.parse(userStr);
  } catch {
    return null;
  }
}

// =====================================================
// VERIFICAR SE ESTÁ AUTENTICADO
// =====================================================

export function isAuthenticated() {
  return getCurrentUser() !== null;
}

// =====================================================
// VERIFICAR ROLE
// =====================================================

export function hasRole(role: 'ADMIN' | 'LAWYER' | 'INTERN') {
  const user = getCurrentUser();
  return user?.role === role;
}

export function isAdmin() {
  return hasRole('ADMIN');
}

